import React, { useEffect, useState } from "react";
import API from "../api";

export default function ReceiptPage() {
  const [receipt, setReceipt] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchReceipt = async () => {
      try {
        const res = await API.get("/checkout/receipt"); // 👈 backend route for latest user receipt
        setReceipt(res.data);
      } catch (err) {
        console.error("Error fetching receipt:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchReceipt();
  }, []);

  if (loading) return <p className="text-center text-gray-500 mt-10">Loading your receipt...</p>;
  if (!receipt) return <p className="text-center text-gray-500 mt-10">No receipt found.</p>;

  return (
    <div className="cart-container">
      <h2>🧾 Your Payment Receipt</h2>

      <div style={{ marginBottom: "10px" }}>
        <p><strong>Name:</strong> {receipt.name}</p>
        <p><strong>Email:</strong> {receipt.email}</p>
        <p><strong>Date:</strong> {new Date(receipt.timestamp).toLocaleString()}</p>
      </div>

      <table>
        <thead>
          <tr>
            <th>Product</th>
            <th>Qty</th>
            <th>Price</th>
            <th>Subtotal</th>
          </tr>
        </thead>
        <tbody>
          {receipt.items.map((item, i) => (
            <tr key={i}>
              <td>{item.name}</td>
              <td>{item.qty}</td>
              <td>${item.price.toFixed(2)}</td>
              <td>${item.subtotal.toFixed(2)}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <h3 className="text-right">Total: ${receipt.total.toFixed(2)}</h3>
    </div>
  );
}
